/*
 * A285469  Positions of 1 in A285467; complement of A285468.
 * https://oeis.org/A285469
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = position of the n-th 1 in A285467, the fixed point of
 *            0->11, 1->0001 (generated by iterating 0->00010001,
 *            1->1111110001); computed by scanning the word
 * Range:     u8 n <= 153, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Validated: standard, pass, 81 terms through n = 8901 (2026-11-08)
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <string.h>
#include <stdint.h>

seq_t a(idx_t n)
{
    static unsigned char *buf = NULL;
    static size_t len = 0;
    static const unsigned char g0[8]  = {0,0,0,1,0,0,0,1};
    static const unsigned char g1[10] = {1,1,1,1,1,1,0,0,0,1};

    if (buf == NULL) {
        buf = (unsigned char *)malloc(2);
        buf[0] = 1;
        buf[1] = 1;
        len = 2;
    }

    for (;;) {
        idx_t ones = 0;
        for (size_t i = 0; i < len; ++i) {
            if (buf[i]) {
                ++ones;
                if (ones == n)
                    return (seq_t)(i + 1);
            }
        }
        size_t zc = len - (size_t)ones;
        size_t new_len = zc * 8 + (size_t)ones * 10;
        unsigned char *nb = (unsigned char *)malloc(new_len);
        unsigned char *p = nb;
        for (size_t i = 0; i < len; ++i) {
            if (buf[i]) {
                memcpy(p, g1, 10);
                p += 10;
            } else {
                memcpy(p, g0, 8);
                p += 8;
            }
        }
        free(buf);
        buf = nb;
        len = new_len;
    }
}
